/**
 * Drift server entry point.
 *
 * Reads config from `.env.local`, builds the Fastify app, attaches the
 * WebSocket server, and listens on `config.apiPort` (defaults to
 * `config.port + 1` so the Fastify server and the Vite dev server don't
 * collide on `PORT=3000`). `tsx watch` invokes this file during
 * `npm run dev`; production launches it via `node dist/server/index.js`
 * (TASK-69).
 *
 * Graceful shutdown closes both the HTTP server and the ws handle so the
 * process exits cleanly when killed by `tsx`/CI.
 */
import { serverConfig } from "./config.js";
import { buildApp } from "./server.js";
import { attachWs } from "./ws.js";

async function main(): Promise<void> {
  const app = await buildApp(serverConfig);
  const ws = attachWs(app, serverConfig.wsPath);

  await app.listen({ port: serverConfig.apiPort, host: "0.0.0.0" });
  app.log.info(
    { port: serverConfig.apiPort, wsPath: serverConfig.wsPath, clientPort: serverConfig.port },
    "drift server listening",
  );

  const shutdown = async (signal: string): Promise<void> => {
    app.log.info({ signal }, "shutting down");
    try {
      await ws.close();
      await app.close();
    } finally {
      process.exit(0);
    }
  };

  process.on("SIGINT", () => void shutdown("SIGINT"));
  process.on("SIGTERM", () => void shutdown("SIGTERM"));
}

main().catch((err: unknown) => {
  // Surface the error then exit with a non-zero code so `tsx watch` respawns.
  console.error("[drift-server] fatal:", err);
  process.exit(1);
});

import { defineConfig } from "vitest/config";
import react from "@vitejs/plugin-react";
import path from "node:path";

const HERE = import.meta.dirname;

/**
 * Vitest config for the Drift workspace.
 *
 * Mirrors the Vite path aliases so tests can use `@shared/*`, `@client/*`,
 * and `@server/*` the same way the runtime code does. The Vite React plugin
 * is wired in so any future component-level tests in `src/client/**` work
 * out of the box.
 *
 * Per-file environments:
 *   - Default: `node` (TASK-1 prereqs, Fastify inject tests, etc.)
 *   - A test file that needs a browser-like environment adds a
 *     `// @vitest-environment happy-dom` pragma as the first line. This
 *     is the Vitest 4 replacement for the removed `environmentMatchGlobs`
 *     option. Used by `src/shared/random.parity.test.ts` (TASK-2) to
 *     prove Node/browser parity of the PRNG.
 *
 * We deliberately use `happy-dom` (not `jsdom`) — it's 10× faster to
 * spin up and we only need the *shape* of `globalThis.TextEncoder` and
 * `Uint8Array`, which both provide.
 */
export default defineConfig({
  plugins: [react()],
  test: {
    environment: "node",
    globals: true,
    include: ["src/**/*.test.ts", "src/**/*.test.tsx", "prereqs.test.ts"],
  },
  resolve: {
    alias: {
      "@shared": path.resolve(HERE, "src/shared"),
      "@client": path.resolve(HERE, "src/client"),
      "@server": path.resolve(HERE, "src/server"),
    },
  },
});

/**
 * Fastify application factory.
 *
 * Exposes a single `buildApp(config)` entry point so tests can `inject()`
 * requests without binding a TCP port. The full route table will grow with
 * subsequent tasks; the only handler that exists today is the `/api/health`
 * smoke check required by TASK-68.
 */
import Fastify, { type FastifyInstance } from "fastify";
import type { ServerConfig } from "./config.js";

export interface BuildAppOptions {
  /** Disable Fastify's startup logger (useful in tests). */
  quietLogger?: boolean;
}

/**
 * Construct a Fastify instance with the Drift baseline:
 *  - JSON body parser enabled (consumed by future REST handlers).
 *  - `/api/health` route returning `{ ok: true, galaxySeed }`.
 *
 * The function is intentionally side-effect free: it does NOT call
 * `app.listen()`. The entrypoint (`src/server/index.ts`) is responsible
 * for binding to a TCP port.
 */
export async function buildApp(
  config: ServerConfig,
  options: BuildAppOptions = {},
): Promise<FastifyInstance> {
  const app = Fastify({
    logger: options.quietLogger ? false : { level: process.env.LOG_LEVEL ?? "info" },
  });

  app.get("/api/health", async () => ({
    ok: true,
    galaxySeed: config.galaxySeed,
  }));

  return app;
}

/**
 * Server smoke tests.
 *
 * Boots a Fastify app via `buildApp()` and exercises the `/api/health`
 * endpoint with `inject()`. No TCP port is bound; the test stays fast and
 * isolated from any other process that might be using `PORT`.
 */
import { describe, it, expect, beforeAll, afterAll } from "vitest";
import type { FastifyInstance } from "fastify";
import { buildApp } from "./server.js";
import { loadConfig } from "./config.js";
import type { HealthPayload } from "@shared/health.js";

describe("server /api/health", () => {
  let app: FastifyInstance;

  beforeAll(async () => {
    const config = loadConfig();
    app = await buildApp(config, { quietLogger: true });
    await app.ready();
  });

  afterAll(async () => {
    await app.close();
  });

  it("returns 200 with ok=true and a galaxySeed", async () => {
    const response = await app.inject({ method: "GET", url: "/api/health" });
    expect(response.statusCode).toBe(200);
    const body = response.json() as HealthPayload;
    expect(body.ok).toBe(true);
    expect(typeof body.galaxySeed).toBe("string");
    expect(body.galaxySeed.length).toBeGreaterThan(0);
  });
});

